import smbus2 as smbus, time

A = 0x48
bus = smbus.SMBus(1)

def swap(v):
    return ((v & 0xff00) >> 8) | ((v & 0x00ff) << 8)

def readAdc(c):
    config = 0x8583 | (c << 11)
    bus.write_i2c_block_data(A, 0x01, list(swap(config & 0xffff)))
    while not bus.read_byte_data(A, 0x00) & 0x8000: pass
    return swap(bus.read_i2c_block_data(A, 0x00, 2)[0] << 8 | bus.read_i2c_block_data(A, 0x00, 2)[1])

try:
    while True:
        for i in range(4):
            print(f"Channel {i}: {readAdc(i)}")
        time.sleep(0.05)
except KeyboardInterrupt:
    pass

