import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# I2C bus and ADS1115 instance
i2c_bus = busio.I2C(board.SCL, board.SDA)
adc = ADS.ADS1115(i2c_bus)

# Analog input channels
channel_list = [AnalogIn(adc, ADS.P0), AnalogIn(adc, ADS.P1), AnalogIn(adc, ADS.P2), AnalogIn(adc, ADS.P3)]

def read_channels():
    """Read all ADC channels and return the values."""
    return [channel.value for channel in channel_list]

def format_output(values):
    """Format the ADC readings into a table row string."""
    return '| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*values)

def print_header():
    """Print the table header."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*range(len(channel_list))))
    print('-' * 37)

def main():
    """Continuously read and print ADC values."""
    try:
        print('Reading ADS1115 values')
        print_header()
        while True:
            try:
                readings = read_channels()
                print(format_output(readings))
                time.sleep(0.5)
            except Exception as bus_error:
                print(f"I2C Error: {bus_error}")
                time.sleep(0.5)
    except KeyboardInterrupt:
        print('\nExiting program')
    except Exception as init_error:
        print(f"Initialization Error: {init_error}")

if __name__ == "__main__":
    main()

