import speech_recognition as sr
import RPi.GPIO as GPIO
import time
import datetime
import os
import random
from picamera2 import Picamera2
import adafruit_dht
import signal
import sys

# Constants and Configuration
LIGHT_PIN = 17  # GPIO pin for controlling the lights
DHT_PIN = 4  # GPIO pin for the DHT11 sensor
WAKE_WORD = "Greenhouse"

# Global variables
lights_on = False
picam2 = None
dht_device = None
simulated_gpio = False

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Exiting program...")
    turn_lights_off()  # Turn off lights before exiting
    if picam2:
        picam2.close()
    if not simulated_gpio:
        GPIO.cleanup()  # Clean up GPIO pins
    sys.exit(0)

# Error handling function
def handle_error(message):
    print(f"Error: {message}")
    # Optionally, log the error to a file

# Voice recognition setup
r = sr.Recognizer()
mic = sr.Microphone()

# GPIO setup with error handling
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    print("GPIO setup successful.")
except Exception as e:
    handle_error(f"GPIO setup failed: {e}")
    print("Falling back to simulated GPIO mode.")
    simulated_gpio = True

# DHT11 sensor setup
try:
    dht_device = adafruit_dht.DHT11(DHT_PIN)
    print("DHT11 sensor setup successful.")
except Exception as e:
    handle_error(f"DHT11 sensor setup failed: {e}")
    dht_device = None

# Camera setup
try:
    picam2 = Picamera2()
    picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
    picam2.start()
    print("Camera setup successful.")
except Exception as e:
    handle_error(f"Camera setup failed: {e}")
    picam2 = None

# Function to turn lights on
def turn_lights_on():
    global lights_on
    if not lights_on:
        if not simulated_gpio:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
        else:
            print("Simulated: Lights turned ON")
        lights_on = True
        print("Lights turned ON")

# Function to turn lights off
def turn_lights_off():
    global lights_on
    if lights_on:
        if not simulated_gpio:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
        else:
            print("Simulated: Lights turned OFF")
        lights_on = False
        print("Lights turned OFF")

# Function to read temperature from DHT11 sensor
def read_temperature():
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                handle_error("DHT11 sensor returned None temperature.")
                return None
        except adafruit_dht.DHTError as e:
            handle_error(f"DHT11 sensor error: {e}")
            return None
        except Exception as e:
            handle_error(f"Unexpected DHT11 sensor error: {e}")
            return None
    else:
        # Simulate temperature reading if DHT11 is not available
        return random.uniform(15, 35)

# Function to capture an image
def capture_image():
    if picam2:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            picam2.capture_file(filename)
            print(f"Image captured: {filename}")
            return filename
        except Exception as e:
            handle_error(f"Camera error: {e}")
            return None
    else:
        print("Camera unavailable.")
        return None

# Main loop
def main():
    global lights_on
    print("Greenhouse Control System started.")

    try:
        while True:
            with mic as source:
                r.adjust_for_ambient_noise(source) # Adjust for background noise
                print("Say something!")
                audio = r.listen(source, timeout=5) # Listen for 5 seconds

            try:
                # Recognize speech using Google Web Speech API
                text = r.recognize_google(audio)
                print(f"You said: {text}")

                # Voice command processing
                if WAKE_WORD.lower() in text.lower():
                    if "turn on the lights" in text.lower():
                        turn_lights_on()
                    elif "turn off the lights" in text.lower():
                        turn_lights_off()
                    elif "what is the temperature" in text.lower():
                        temperature = read_temperature()
                        if temperature is not None:
                            print(f"Temperature: {temperature:.1f}°C")
                        else:
                            print("Temperature could not be read.")
                    elif "take a picture" in text.lower():
                        image_file = capture_image()
                        if image_file:
                            print(f"Image saved as {image_file}")
                        else:
                            print("Image capture failed.")
                    else:
                        print("Unknown command.")
                else:
                    print("Wake word not detected.")

            except sr.UnknownValueError:
                print("Could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")
            except Exception as e:
                handle_error(f"Voice recognition error: {e}")

            time.sleep(1)  # Small delay to prevent CPU hogging

    except KeyboardInterrupt:
        print("Program interrupted.")
    finally:
        turn_lights_off()
        if picam2:
            picam2.close()
        if not simulated_gpio:
            GPIO.cleanup()
        print("Greenhouse Control System stopped.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

