# Simple Motion Detection Script for Raspberry Pi Zero W
# Uses picamera2 library to capture images and detect motion.

import time
import numpy as np
from picamera2 import Picamera2

# Configuration
MOTION_THRESHOLD = 10  # Adjust this value to fine-tune the sensitivity
CAPTURE_INTERVAL = 2  # Seconds between image captures

def initialize_camera():
    """Initializes the camera with basic settings."""
    try:
        camera = Picamera2()
        config = camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        camera.configure(config)
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera):
    """Captures an image from the camera and returns it as a numpy array."""
    try:
        image = camera.capture_array()
        return image
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def calculate_average_pixel_value(image):
    """Calculates the average pixel value of an image."""
    if image is None:
        return 0
    return np.mean(image)

def detect_motion(current_average, baseline_average, threshold):
    """Detects motion based on the difference between current and baseline average pixel values."""
    return abs(current_average - baseline_average) > threshold

def save_image(image, filename="motion.jpg"):
    """Saves the image to a file."""
    try:
        from PIL import Image
        img = Image.fromarray(image)
        img.save(filename)
        print(f"Motion detected! Image saved to {filename}")
    except ImportError:
        print("PIL (Pillow) is not installed. Install it with: pip install Pillow")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    """Main function to run the motion detection."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        # Capture initial baseline image
        baseline_image = capture_image(camera)
        baseline_average = calculate_average_pixel_value(baseline_image)

        while True:
            # Capture current image
            current_image = capture_image(camera)
            current_average = calculate_average_pixel_value(current_image)

            # Detect motion
            if detect_motion(current_average, baseline_average, MOTION_THRESHOLD):
                save_image(current_image)
                baseline_average = current_average  # Update baseline

            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if camera:
            camera.stop()
            camera.close()
            print("Camera resources released.")

if __name__ == "__main__":
    main()

