# Import necessary libraries
from picamera2 import Picamera2
import RPi.GPIO as GPIO
import serial
import time
import cv2
import numpy as np
import io
import logging
import os
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants and configuration
CAMERA_WIDTH = 160
CAMERA_HEIGHT = 120
CAMERA_FRAMERATE = 16
SERIAL_PORT = "/dev/ttyACM0"
SERIAL_BAUDRATE = 115200
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY_CYCLE = 7.0  # Use float for duty cycle
MIN_TARGET_AREA = 10
X_THRESHOLD = 24
SEARCH_RANGE = 12
SERVO_INCREMENT = 0.5
MAX_ADJUSTMENT_ATTEMPTS = 3
CAMERA_RECONNECT_DELAY = 5  # Seconds to wait before reconnecting camera
CAMERA_MAX_RECONNECT_ATTEMPTS = 3
SERIAL_RECONNECT_DELAY = 5  # Seconds to wait before reconnecting serial
SERIAL_MAX_RECONNECT_ATTEMPTS = 3

# Global variables
arduino = None
camera = None
pwm_servo_1 = None
pwm_servo_2 = None
search_angle = 0
is_tracking = False

# Custom exception classes
class CameraInitializationError(Exception):
    pass

class SerialCommunicationError(Exception):
    pass

class GPIOInitializationError(Exception):
    pass

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info('Shutting down gracefully...')
    global camera, arduino, pwm_servo_1, pwm_servo_2

    # Stop the camera
    if camera:
        try:
            camera.stop()
            camera.close()
            logging.info("Camera stopped and closed.")
        except Exception as e:
            logging.error(f"Error stopping/closing camera: {e}")

    # Stop the Arduino connection
    if arduino:
        try:
            arduino.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")

    # Clean up GPIO pins
    if pwm_servo_1 or pwm_servo_2:
        try:
            pwm_servo_1.stop()
            pwm_servo_2.stop()
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Configuration management functions
def load_configuration(config_file="config.txt"):
    """Loads configuration parameters from a file."""
    global CAMERA_WIDTH, CAMERA_HEIGHT, CAMERA_FRAMERATE, SERIAL_PORT, SERIAL_BAUDRATE, \
           SERVO_PIN_1, SERVO_PIN_2, SERVO_FREQUENCY, SERVO_CENTER_DUTY_CYCLE, MIN_TARGET_AREA, \
           X_THRESHOLD, SEARCH_RANGE, SERVO_INCREMENT, MAX_ADJUSTMENT_ATTEMPTS, CAMERA_RECONNECT_DELAY, \
           CAMERA_MAX_RECONNECT_ATTEMPTS, SERIAL_RECONNECT_DELAY, SERIAL_MAX_RECONNECT_ATTEMPTS

    try:
        with open(config_file, "r") as f:
            for line in f:
                if "=" in line:
                    key, value = line.strip().split("=", 1)
                    try:
                        if key == "CAMERA_WIDTH":
                            CAMERA_WIDTH = int(value)
                        elif key == "CAMERA_HEIGHT":
                            CAMERA_HEIGHT = int(value)
                        elif key == "CAMERA_FRAMERATE":
                            CAMERA_FRAMERATE = int(value)
                        elif key == "SERIAL_PORT":
                            SERIAL_PORT = value
                        elif key == "SERIAL_BAUDRATE":
                            SERIAL_BAUDRATE = int(value)
                        elif key == "SERVO_PIN_1":
                            SERVO_PIN_1 = int(value)
                        elif key == "SERVO_PIN_2":
                            SERVO_PIN_2 = int(value)
                        elif key == "SERVO_FREQUENCY":
                            SERVO_FREQUENCY = int(value)
                        elif key == "SERVO_CENTER_DUTY_CYCLE":
                            SERVO_CENTER_DUTY_CYCLE = float(value)
                        elif key == "MIN_TARGET_AREA":
                            MIN_TARGET_AREA = int(value)
                        elif key == "X_THRESHOLD":
                            X_THRESHOLD = int(value)
                        elif key == "SEARCH_RANGE":
                            SEARCH_RANGE = int(value)
