def _convert_frame_to_opencv_rgb(frame: np.ndarray) -> np.ndarray:
    """Converts a Picamera2 frame to an OpenCV RGB NumPy array."""
    try:
        with MappedArray(frame) as ma:
            frame_rgb = ma.array
            if frame_rgb.flags.c_contiguous:
                return frame_rgb
            else:
                return np.ascontiguousarray(frame_rgb, dtype=np.uint8)
    except Exception as e:
        _logger.error("Error converting frame to OpenCV RGB: %s", e)
        return None

def _frame_diff(frame1: np.ndarray, frame2: np.ndarray) -> Optional[np.ndarray]:
