import io
import logging
import threading
import time
import signal
import sys
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2, MappedArray
from picamera2.devices import Hailo
from picamera2.encoders import H264Encoder, Quality
from picamera2.outputs import FileOutput

# Placeholder for WebSocket handler (replace with your actual implementation)
class WebSocketHandler:
    def has_connections(self) -> bool:
        return False  # Replace with your logic
    def broadcast(self, data: bytes) -> None:
        pass  # Replace with your logic

_logger = logging.getLogger(__name__)

# Type aliases for clarity
Frame = np.ndarray
FrameData = bytes


def _convert_to_opencv_frame(frame_data: FrameData) -> Optional[Frame]:
    """Converts raw frame data (e.g., JPEG) to an OpenCV frame (e.g., BGR)."""
    try:
        data = np.frombuffer(frame_data, dtype=np.uint8)
        return cv2.imdecode(data, cv2.IMREAD_COLOR)
    except Exception as e:
        _logger.error(f"Error converting frame data: {e}", exc_info=True)
        return None


class CameraStreamBuffer:
    """Buffers and broadcasts camera stream data via WebSockets."""

    def __init__(self, websocket_handler: WebSocketHandler):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be an instance of WebSocketHandler")
        self._websocket_handler = websocket_handler
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._frame_marker = b'\xff\xd8'  # Start of Frame marker

    def write(self, data: bytes) -> int:
        """Writes data to the buffer, detecting new frames and broadcasting."""
        try:
            with self._lock:
                self._buffer.write(data)
                # Keep only the last complete frame in the buffer
                buffer_value = self._buffer.getvalue()
                frame_start = buffer_value.find(self._frame_marker)
                if frame_start >= 0:
                    frame_data = buffer_value[frame_start:]
                    if self._websocket_handler.has_connections():
                        self._websocket_handler.broadcast(frame_data)
                    # Update the buffer to keep only the last partial frame
                    self._buffer = io.BytesIO()
                    self._buffer.write(buffer_value[frame_start:])
                else:
                    # If no frame marker found, keep the data in the buffer
                    self._buffer = io.BytesIO()
                    self._buffer.write(buffer_value)
                return len(data)
        except Exception as e:
            _logger.error(f"Error in CameraStreamBuffer: {e}", exc_info=True)
            return 0

    def flush(self) -> None:
        """Flushes any remaining data in the buffer."""
        try:
            with self._lock:
                buffer_value = self._buffer.getvalue()
                if buffer_value:
                    _logger.debug(f"Flushing {len(buffer_value)} bytes from stream buffer")
                    if self._websocket_handler.has_connections():
                        self._websocket_handler.broadcast(buffer_value)
                    self._buffer.seek(0)
                    self._buffer.truncate()
        except Exception as e:
            _logger.error(f"Error flushing CameraStreamBuffer: {e}", exc_info=True)


class MotionDetectionBuffer:
    """Buffers and detects motion in camera frames."""

    def __init__(
        self,
        detect_motion_function: Callable[[Frame, Frame], None],
        initial_previous_frame: Optional[Frame] = None,
    ):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self._detect_motion = detect_motion_function
        self._previous_frame: Optional[Frame] = initial_previous_frame
        self._current_frame: Optional[Frame] = None
        self._buffer = io.BytesIO()
        self._frame_marker = b'\xff\xd8'  # Start of Frame marker
        self._lock = threading.Lock()

    def _process_frame_data(self, frame_data: FrameData) -> None:
        """Processes frame data, updating frames and detecting motion."""
        frame = _convert_to_opencv_frame(frame_data)
        if frame is None:
            return

        with self._lock:
            self._previous_frame = self._current_frame
            self._current_frame = frame

            if self._previous_frame is not None:
                try:
                    self._detect_motion(self._previous_frame.copy(), self._current_frame.copy())
                except Exception as e:
                    _logger.error(f"Error in motion detection function: {e}", exc_info=True)

    def write(self, data: bytes) -> int:
        """Writes data, detecting new frames and processing complete frames."""
        try:
            with self._lock:
                self._buffer.write(data)
                buffer_value = self._buffer.getvalue()
                frame_start = buffer_value.find(self._frame_marker)

                if frame_start >= 0:
                    frame_data = buffer_value[frame_start:]
                    self._process_frame_data(frame_data)
                    # Keep only the last partial frame in the buffer
                    self._buffer = io.BytesIO()
                    self._buffer.write(buffer_value[frame_start:])
                else:
                    # If no frame marker found, keep the data in the buffer
                    self._buffer = io.BytesIO()
                    self._buffer.write(buffer_value)
                return len(data)
        except Exception as e:
            _logger.error(f"Error in MotionDetectionBuffer: {e}", exc_info=True)
            return 0

    def flush(self) -> None:
        """Flushes any remaining data and processes the final frame."""
        try:
            with self._lock:
                buffer_value = self._buffer.getvalue()
                if buffer_value:
                    _logger.debug(f"Flushing {len(buffer_value)} bytes from motion buffer")
                    self._process_frame_data(buffer_value)
                    self._buffer.seek(0)
                    self._buffer.truncate()
        except Exception as e:
            _logger.error(f"Error flushing MotionDetectionBuffer: {e}", exc_info=True)


def _signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    _logger.info(f"Received signal {sig}. Shutting down...")
    sys.exit(0)


def _configure_camera(resolution=(640, 480), frame_rate=10) -> Picamera2:
    """Configures the camera with the specified resolution and frame rate."""
    camera = Picamera2()
    camera.preview_configuration.main.size = resolution
    camera.preview_configuration.main.format = "jpeg"
    camera.preview_configuration.controls.FrameRate = frame_rate
    camera.preview_configuration.align()
    camera.configure("preview")
    return camera


def run_camera_stream(
    resolution=(640, 480),
    frame_rate=10,
    output_path: Optional[str] = None,
    detect_motion_function: Optional[Callable[[Frame, Frame], None]] = None,
    websocket_handler: Optional[WebSocketHandler] = None,
):
    """Runs the camera stream with optional motion detection and streaming."""

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = _configure_camera(resolution, frame_rate)

    motion_buffer = None
    stream_buffer = None

    if detect_motion_function:
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        motion_buffer = MotionDetectionBuffer(detect_motion_function)

    if websocket_handler:
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be an instance of WebSocketHandler")
        stream_buffer = CameraStreamBuffer(websocket_handler)

    encoder = H264Encoder(quality=Quality.MAX_QUALITY)
    camera.start_encoder(encoder, output=FileOutput(output_path) if output_path else None)

    if stream_buffer:
        camera.outputs[0].set_buffer_allocator(
            lambda req: MappedArray(
                (req.size.width, req.size.height, 3), "jpeg", req.request_id
            )
        )
        camera.outputs[0].write = stream_buffer.write

    if motion_buffer:
        camera.outputs[0].set_buffer_allocator(
            lambda req: MappedArray(
                (req.size.width, req.size.height, 3), "jpeg", req.request_id
            )
        )
        camera.outputs[0].write = motion_buffer.write

    try:
        _logger.info("Camera started. Press Ctrl+C to stop.")
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        _logger.info("Stopping camera...")
    finally:
        if motion_buffer:
            motion_buffer.flush()
        if stream_buffer:
            stream_buffer.flush()
        camera.stop_encoder()

