import smbus2
import time

# I2C address of the PCF8574 port expander
PCF8574_ADDRESS = 0x20

# Initialize the I2C bus on the Raspberry Pi
i2c_bus = smbus2.SMBus(1)

# Configure all pins on the PCF8574 as inputs with pull-up resistors enabled
def initialize_expander():
    """Set all pins on the PCF8574 as inputs with pull-up resistors enabled."""
    try:
        i2c_bus.write_byte(PCF8574_ADDRESS, 0xFF)
