#!/usr/bin/env python3

import time
import smbus2
import logging
from ina219 import INA219, DeviceRangeError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEVICE_BUS = 1
DEVICE_ADDR = 0x17
SUPPLY_SHUNT_RESISTOR = 0.00725
BATTERY_SHUNT_RESISTOR = 0.005
INA219_SUPPLY_ADDRESS = 0x40
INA219_BATTERY_ADDRESS = 0x45
INA219_SUPPLY_RANGE = 32  # mA range for Raspberry Pi power supply
INA219_BATTERY_RANGE = 16  # mA range for battery

# Global variables
bus = None
ina_supply = None
ina_battery = None

def initialize_i2c_bus(bus_num=DEVICE_BUS):
    """Initializes the I2C bus."""
    global bus
    try:
        bus = smbus2.SMBus(bus_num)
        logging.info(f"I2C bus {bus_num} initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        return False

def initialize_ina219_supply(shunt_resistor=SUPPLY_SHUNT_RESISTOR, bus_num=DEVICE_BUS, address=INA219_SUPPLY_ADDRESS):
    """Initializes the INA219 sensor for Raspberry Pi power supply."""
    global ina_supply
    try:
        ina_supply = INA219(shunt_resistor, busnum=bus_num, address=address)
        ina_supply.configure(range=INA219_SUPPLY_RANGE)
        logging.info("INA219 supply sensor initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize INA219 supply sensor: {e}")
        return False

def initialize_ina219_battery(shunt_resistor=BATTERY_SHUNT_RESISTOR, bus_num=DEVICE_BUS, address=INA219_BATTERY_ADDRESS):
    """Initializes the INA219 sensor for battery."""
    global ina_battery
    try:
        ina_battery = INA219(shunt_resistor, busnum=bus_num, address=address)
        ina_battery.configure(range=INA219_BATTERY_RANGE)
        logging.info("INA219 battery sensor initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize INA219 battery sensor: {e}")
        return False

def read_ups_data(device_address=DEVICE_ADDR, bus_num=DEVICE_BUS):
    """Reads data from the UPS Plus device via I2C."""
    try:
        data = []
        for i in range(256):
            try:
                data.append(bus.read_byte_data(device_address, i))
            except Exception as e:
                logging.warning(f"Error reading byte at register 0x{i:02X}: {e}")
                data.append(None)  # Append None to indicate a read failure
        return data
    except Exception as e:
        logging.error(f"Failed to read data from UPS Plus device: {e}")
        return None

def process_ups_data(data_block):
    """Processes the raw data read from the UPS Plus device."""
    if data_block is None or len(data_block) < 19:
        logging.error("Invalid UPS data block received.")
        return None

    try:
        ups_data = {}
        ups_data["processor_voltage"] = (data_block[3] << 8) | data_block[2]
        ups_data["raspberry_pi_voltage"] = (data_block[5] << 8) | data_block[4]
        ups_data["battery_port_voltage"] = (data_block[7] << 8) | data_block[6]
        ups_data["type_c_voltage"] = (data_block[9] << 8) | data_block[8]
        ups_data["micro_usb_voltage"] = (data_block[11] << 8) | data_block[10]
        ups_data["full_battery_voltage"] = (data_block[13] << 8) | data_block[12]
        ups_data["empty_battery_voltage"] = (data_block[15] << 8) | data_block[14]
        ups_data["battery_protection_voltage"] = (data_block[17] << 8) | data_block[16]
        ups_data["battery_temperature"] = (data_block[19] << 8) | data_block[18]

        return ups_data
    except Exception as e:
        logging.error(f"Failed to process UPS data: {e}")
        return None

def read_supply_metrics():
    """Reads and prints Raspberry Pi power supply metrics using INA219."""
    global ina_supply
    if ina_supply is None:
        logging.warning("INA219 supply sensor not initialized.")
        return

    try:
        supply_voltage = ina_supply.voltage()
        supply_current = ina_supply.current()
        supply_power = ina_supply.power()

        print("Raspberry Pi Power Supply Metrics:")
        print(f"  Voltage: {supply_voltage:.3f} V")
        print(f"  Current: {supply_current:.3f} mA")
        print(f"  Power: {supply_power:.3f} mW")
    except Exception as e:
        logging.error(f"Error reading supply metrics: {e}")

def read_battery_metrics():
    """Reads and prints battery metrics using INA219."""
    global ina_battery
    if ina_battery is None:
        logging.warning("INA219 battery sensor not initialized.")
        return

    try:
        battery_voltage = ina_battery.voltage()
        battery_current = ina_battery.current()
        battery_power = ina_battery.power()

        print("Battery Metrics:")
        print(f"  Voltage: {battery_voltage:.3f} V")
        print(f"  Current: {battery_current:.3f} mA")
        print(f"  Power: {battery_power:.3f} mW")

        if battery_current > 0:
            print("  Charging")
        elif battery_current < 0:
            print("  Discharging")
        else:
            print("  Idle")
    except DeviceRangeError:
        print("  Battery power is too high.")
    except Exception as e:
        logging.error(f"Error reading battery metrics: {e}")

def main():
    """Main function to read and display UPS Plus data."""
    if not initialize_i2c_bus():
        return

    if not initialize_ina219_supply():
        return

    if not initialize_ina219_battery():
        return

    try:
        while True:
            read_supply_metrics()

            read_battery_metrics()

            ups_data = read_ups_data()
            if ups_data:
                processed_data = process_ups_data(ups_data)
                if processed_data:
                    print("UPS Plus Data:")
                    for key, value in processed_data.items():
                        print(f"  {key}: {value}")

                    if processed_data["type_c_voltage"] > 4000:
                        print("Charging through Type C")
                    elif processed_data["micro_usb_voltage"] > 4000:
                        print("Charging via Micro USB")
                    else:
                        print("Not charging")
            else:
                logging.error("Failed to read UPS data.")

            time.sleep(2)
    except KeyboardInterrupt:
        logging.info("Exiting program.")
    finally:
        if bus:
            bus.close()
            logging.info("I2C bus closed.")

if __name__ == "__main__":
    main()

