# environmental_monitor.py
# Reads temperature and humidity from a UART sensor on Raspberry Pi
import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0


def read_sensor_data(serial_connection):
    """Reads a line from the serial port and returns the temperature and humidity."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            fields = line.split(',')
            if len(fields) == 2:
                temperature = float(fields[0])
                humidity = float(fields[1])
                return temperature, humidity
        return None, None
    except ValueError:
        print("Error: Invalid data format received from sensor.")
        return None, None
    except serial.SerialException as e:
        print(f"Error: Serial communication error: {e}")
        return None, None


def process_data(temperature, humidity):
    """Prints the temperature and humidity, and triggers alerts if necessary."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
        if temperature > TEMP_THRESHOLD:
            print('Alert: Temperature exceeds threshold!')
        if humidity > HUMIDITY_THRESHOLD:
            print('Alert: Humidity exceeds threshold!')


def main():
    """Main function to read sensor data and process it."""
    try:
        # Initialize serial connection
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
            while True:
                temperature, humidity = read_sensor_data(ser)
                if temperature is not None and humidity is not None:
                    process_data(temperature, humidity)
                time.sleep(1)
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        print("Program finished.")


if __name__ == "__main__":
    main()

