import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

GPIO.setwarnings(False)
SERVER_NAME = "RPi_DOGServer"

# Help messages for commands
help_messages = {
    "start": "Start the server and log data to a file. Usage: start <filename>",
    "stop": "Stop the server. Usage: stop",
    "display": "Display the log file content. Usage: display",
    "send": "Send data using DOGProtocol. Usage: send <data>",
    "receive": "Receive data using DOGProtocol. Usage: receive",
    "write": "Write data directly to the log file. Usage: write <data>",
    "exit": "Exit the server. Usage: exit",
    "help": "Display help information. Usage: help [command]"
}

class DOGServer:
    """A server for receiving and logging data using the DOGProtocol, with command-line interface."""

    def __init__(self):
        """Initializes the server and GPIO."""
        self.is_running = False
        self.log_file = None
        self.log_file_path = None
        self.receive_thread = None
        GPIO.setmode(GPIO.BCM)  # Use Broadcom pin numbering

    def _log(self, message):
        """Writes a message to the log file."""
        if self.log_file:
            self.log_file.write(message + "\n")
            self.log_file.flush()  # Ensure data is written immediately

    def _receive_loop(self):
        """Continuously receives data and logs it to the file."""
        try:
            while self.is_running:
                data = DOG.receive()
                if data:  # Check if data is not empty
                    self._log(data)
        except Exception as e:
            print(f"Error in receive thread: {e}")
            self.stop() # Stop the server in case of error

    def start(self, log_file_path):
        """Starts the server and the receive thread."""
        if self.is_running:
            print("Server is already running.")
            return

        try:
            self.log_file_path = log_file_path
            self.log_file = open(self.log_file_path, "a")  # Append mode
            self.is_running = True
            self.receive_thread = threading.Thread(target=self._receive_loop, name="ReceiveThread", daemon=True)
            self.receive_thread.start()
            print(f"Server started. Logging to {self.log_file_path}")
        except Exception as e:
            print(f"Error starting server: {e}")
            self.stop()

    def stop(self):
        """Stops the server and cleans up resources."""
        if not self.is_running:
            print("Server is not running.")
            return

        self.is_running = False
        if self.receive_thread:
            self.receive_thread.join(timeout=2) # Wait for thread to finish, but with a timeout
            if self.receive_thread.is_alive():
                print("Receive thread did not terminate in time.")
            else:
                print("Receive thread stopped.")

        if self.log_file:
            try:
                self.log_file.close()
                print("Log file closed.")
            except Exception as e:
                print(f"Error closing log file: {e}")
            finally:
                self.log_file = None

        try:
            GPIO.cleanup()  # Clean up GPIO pins
            print("GPIO cleaned up.")
        except Exception as e:
            print(f"Error cleaning up GPIO: {e}")

        print("Server stopped.")

    def display(self):
        """Displays the content of the log file."""
        if not self.log_file_path:
            print("No log file is currently open.")
            return

        try:
            with open(self.log_file_path, "r") as f:
                print(f.read())
        except FileNotFoundError:
            print("Log file not found.")
        except Exception as e:
            print(f"Error displaying log file: {e}")

    def send(self, data):
        """Sends data using DOGProtocol."""
        if not self.is_running:
            print("Server is not running. Use 'start' command first.")
            return
        try:
            DOG.send(data)
            print(f"Sent: {data}")
        except Exception as e:
            print(f"Error sending data: {e}")

    def receive(self):
        """Receives data using DOGProtocol (should only be called once per server cycle)."""
        if not self.is_running:
            print("Server is not running. Use 'start' command first.")
            return None
        try:
            data = DOG.receive()
            if data:
                print(f"Received: {data}")
                return data
            else:
                print("No data received.")
                return None
        except Exception as e:
            print(f"Error receiving data: {e}")
            return None

    def write(self, data):
        """Writes data directly to the log file."""
        if not self.log_file:
            print("No log file is currently open.")
            return
        try:
            self._log(data)
            print(f"Wrote to log: {data}")
        except Exception as e:
            print(f"Error writing to log file: {e}")

    def help(self, command=None):
        """Displays help information."""
        if command:
            message = help_messages.get(command.lower())
            if message:
                print(message)
            else:
                print(f"No help found for command '{command}'.")
        else:
            print("Available commands:")
            for cmd in help_messages:
                print(f"- {cmd}")
            print("Use 'help <command>' for more details.")

    def exit(self):
        """Stops the server and exits."""
        self.stop()
        print("Exiting.")
        sys.exit(0)

    def run(self):
        """Main loop of the server."""
        print(f"{SERVER_NAME} started. Type 'help' for available commands.")
        while True:
            try:
                command = input("JAYES@ROVER53:\t").strip().split()
                if not command:
                    continue

                cmd_name = command[0].lower()
                args = command[1:]

                # Dispatch commands
                if cmd_name == "start":
                    if len(args) != 1:
                        print(help_messages["start"])
                    else:
                        self.start(args[0])
                elif cmd_name == "stop":
                    self.stop()
                elif cmd_name == "display":
                    self.display()
                elif cmd_name == "send":
                    self.send(" ".join(args))  # Join arguments for the data string
                elif cmd_name == "receive":
                    self.receive()
                elif cmd_name == "write":
                    self.write(" ".join(args)) # Join arguments for the data string
                elif cmd_name == "exit":
                    self.exit()
                elif cmd_name == "help":
                    self.help(" ".join(args) if args else None) # Join arguments for the command
                else:
                    print("Invalid command. Type 'help' for available commands.")

            except KeyboardInterrupt:
                print("\nKeyboard interrupt detected. Exiting.")
                self.stop()
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    server = DOGServer()
    server.run()

