# A simple line-following robot for beginners using two TCRT5000 IR sensors.
# Hardware: Raspberry Pi 3 B+, two TCRT5000 sensors.
# Connect the left sensor to GPIO 5 and the right sensor to GPIO 6.

import RPi.GPIO as GPIO
import time

# Define the GPIO pins for the IR sensors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

def setup_gpio():
    """Set up the GPIO pins for the IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)  # Use BCM pin numbering
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)  # Set left sensor pin as input
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN) # Set right sensor pin as input
        print("GPIO setup complete.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False  # Indicate setup failure
    return True  # Indicate success

def read_sensors():
    """Read the state of the IR sensors."""
    try:
        left_state = GPIO.input(LEFT_SENSOR_PIN)
        right_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_state, right_state
    except Exception as e:
        print(f"Error reading sensors: {e}")
        return None, None  # Return None values to indicate error

def decide_direction(left_state, right_state):
    """Decide the robot's direction based on sensor readings."""
    if left_state == 0 and right_state == 0:
        return "Search"  # Both sensors see the line
    elif left_state == 0:
        return "Turn Right"  # Only the left sensor sees the line
    elif right_state == 0:
        return "Turn Left"  # Only the right sensor sees the line
    else:
        return "Forward"  # Neither sensor sees the line

def main():
    """Main function to run the line-following robot."""
    if not setup_gpio():
        print("GPIO setup failed. Exiting.")
        return

    try:
        for i in range(10):  # Run for 10 samples
            left_state, right_state = read_sensors()

            if left_state is not None and right_state is not None:
                direction = decide_direction(left_state, right_state)
                print(f"Sample {i+1}: Left={left_state}, Right={right_state}, Direction={direction}")
            else:
                print("Skipping sample due to sensor error.")

            time.sleep(0.5)  # Wait 0.5 seconds

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO pins
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

