    global shutdown_flag
    shutdown_flag = True
    print("Shutting down gracefully...")

def initialize_gpio():
    """Initializes the GPIO pins for the LEDs."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(GREEN_LED_PIN, GPIO.OUT)
    GPIO.setup(RED_LED_PIN, GPIO.OUT)

def cleanup_gpio():
    """Cleans up the GPIO pins."""
    GPIO.cleanup()

def sentiment_analysis(text):
    """Performs sentiment analysis on the given text using TextBlob."""
    try:
        blob = TextBlob(text)
        polarity = blob.sentiment.polarity
        return polarity
    except Exception as e:
        log_error(f"Sentiment analysis error: {e}")
        return None

def log_sentiment(feedback, polarity):
    """Logs the sentiment analysis results to the log file."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - Feedback: {feedback}, Polarity: {polarity}\n"
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def append_to_json(data):
    """Appends the given data to the JSON file, maintaining a valid array."""
    try:
        if os.path.exists(DATA_FILE):
            with open(DATA_FILE, 'r') as jsonfile:
                try:
                    json_data = json.load(jsonfile)
                except json.JSONDecodeError:
                    json_data = []
        else:
            json_data = []

        json_data.append(data)

        with open(DATA_FILE, 'w') as jsonfile:
            json.dump(json_data, jsonfile)
    except IOError as e:
        print(f"Error writing to JSON file: {e}")

def control_leds(polarity):
    """Controls the LEDs based on the sentiment polarity."""
    try:
        if polarity > 0.2:
            GPIO.output(GREEN_LED_PIN, GPIO.HIGH)
            GPIO.output(RED_LED_PIN, GPIO.LOW)
        elif polarity < -0.2:
            GPIO.output(GREEN_LED_PIN, GPIO.LOW)
            GPIO.output(RED_LED_PIN, GPIO.HIGH)
        else:
            GPIO.output(GREEN_LED_PIN, GPIO.LOW)
            GPIO.output(RED_LED_PIN, GPIO.LOW)
    except Exception as e:
        log_error(f"LED control error: {e}")

def log_error(message):
    """Logs an error message to the log file with a timestamp."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    error_message = f"{timestamp} - ERROR: {message}\n"
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(error_message)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to orchestrate the sentiment analysis and LED control."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        initialize_gpio()
        print("Sentiment analysis system started.")

        last_pos = 0
        while not shutdown_flag:
            try:
                with open(FEEDBACK_FILE, 'r') as feedbackfile:
                    feedbackfile.seek(last_pos)
                    new_lines = feedbackfile.readlines()
                    last_pos = feedbackfile.tell()

                for line in new_lines:
                    line = line.strip()
                    if line:
                        polarity = sentiment_analysis(line)
                        if polarity is not None:
                            log_sentiment(line, polarity)
                            data = {"feedback": line, "polarity": polarity, "timestamp": datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
                            append_to_json(data)
                            control_leds(polarity)

            except FileNotFoundError:
                log_error("Feedback file not found.")
            except IOError as e:
                log_error(f"Error reading feedback file: {e}")
            except Exception as e:
                log_error(f"An unexpected error occurred: {e}")

            time.sleep(SLEEP_INTERVAL)

    finally:
        cleanup_gpio()
        print("Sentiment analysis system stopped.")

if __name__ == "__main__":
    main()

