import json
import RPi.GPIO as GPIO
import logging
import signal
import sys
from gpiozero import PWMOutputDevice, OutputDevice
from typing import Callable, Any, Dict, List

class PIDHandler:
    """
    Manages PID controllers and error output signal.
    """

    def __init__(self, config: Dict[str, Any], logger: logging.Logger):
        """
        Initializes PIDHandler with configuration and logger.

        Args:
            config: Configuration dictionary.
            logger: Logger instance.
        """
        self.config = config
        self.logger = logger
        self.pids: List[Dict[str, Any]] = []
        self.subscriptions: Dict[str, List[Callable[[Any], None]]] = {}
        self.subscription_kwargs: Dict[str, Dict[str, Any]] = {}
        self.pid_params: Dict[str, Dict[str, Any]] = {}
        self.control_limits: Dict[str, Dict[str, Any]] = {}
        self.global_err_state: bool = False
        self.error_output_device = None

        # GPIO setup based on config
        try:
            if self.config.get("error_output", {}).get("pwm", False):
                self.error_output_device = PWMOutputDevice(18, frequency=1000)  # Example frequency
                self.logger.info("Error output using PWM.")
            else:
                self.error_output_device = OutputDevice(15)
                self.logger.info("Error output using digital pin.")
        except Exception as e:
            self.logger.error(f"Error initializing error output: {e}")
            self.error_output_device = None

        self.setup_signals()

    def setup_signals(self) -> None:
        """Sets up signal handlers for graceful shutdown."""
        signal.signal(signal.SIGINT, self.handle_signal)
        signal.signal(signal.SIGTERM, self.handle_signal)

    def handle_signal(self, signum: int, frame: Any) -> None:
        """Handles signals for graceful shutdown."""
        self.logger.info(f"Received signal {signum}. Shutting down.")
        self.cleanup()
        sys.exit(0)

    def cleanup(self) -> None:
        """Releases resources."""
        if self.error_output_device:
            try:
                self.error_output_device.close()
            except Exception as e:
                self.logger.error(f"Error cleaning up error output: {e}")

    def update_error_output(self) -> None:
        """Updates the error output signal based on global error state."""
        if self.error_output_device:
            try:
                if self.global_err_state:
                    if isinstance(self.error_output_device, PWMOutputDevice):
                        self.error_output_device.value = 1.0  # Full duty cycle
                    else:
                        self.error_output_device.on()
                else:
                    if isinstance(self.error_output_device, PWMOutputDevice):
                        self.error_output_device.value = 0.0
                    else:
                        self.error_output_device.off()
            except Exception as e:
                self.logger.error(f"Error updating error output: {e}")

    def set_error_output(self, state: bool) -> None:
        """Sets the global error state and updates the output."""
        self.global_err_state = state
        self.update_error_output()

    def register_subscription(
        self,
        channel: str,
        callback: Callable[[Any], None],
        kwargs: Dict[str, Any] = None,
    ) -> None:
        """
        Registers a subscription to a specific channel.

        Args:
            channel: The channel to subscribe to.
            callback: The function to call when a message is received.
            kwargs: Keyword arguments to pass to the callback.
        """
        if channel not in self.subscriptions:
            self.subscriptions[channel] = []
            self.subscription_kwargs[channel] = []
        self.subscriptions[channel].append(callback)
        self.subscription_kwargs[channel].append(kwargs if kwargs else {})
        self.logger.info(f"Subscribed to channel: {channel}")

    def handle_message(self, sock: zmq.Socket, sub_filter: str) -> None:
        """
        Handles a received message, updating PID parameters, calling subscriptions,
        and managing the global error state.

        Args:
            sock: The socket the message was received on.
            sub_filter: The filter used to subscribe to the channel.
        """
        try:
            [channel, content] = sock.recv_multipart(flags=zmq.NOBLOCK)

            channel_str = channel.decode('utf-8')
            if channel_str != sub_filter:
                return

            try:
                message = json.loads(content.decode('utf-8'))
            except json.JSONDecodeError:
                self.logger.error(f"Invalid JSON received: {content}")
                return

            self.logger.debug(f"Received message: {message} on channel: {channel_str}")

            action = message.get('action')

            if action == 'update_pid_params':
                self._update_pid_params(message)
            elif action == 'set_control_limits':
                self._set_control_limits(message)
            elif action == 'reset_pid':
                self._reset_pid(message)
            elif action == 'get_status':
                self._get_status(message)
            elif action == 'set_log_level':
                self._set_log_level(message.get('value', 'INFO'))
            elif action == 'trigger_error':
                self._trigger_error(message)
            elif action == 'clear_error':
                self._clear_error(message)
            elif action == 'subscribe':  # Placeholder, should not reach here
                pass
            else:
                self.logger.warning(f"Unknown action: {action}")

            # Dispatch to subscriptions after processing other actions
            if channel_str in self.subscriptions:
                for i, callback in enumerate(self.subscriptions[channel_str]):
                    try:
                        callback(message, **self.subscription_kwargs[channel_str][i])
                    except Exception as e:
                        self.logger.error(f"Error in subscription callback: {e}")

        except zmq.ZMQError as e:
            if e.errno == zmq.EAGAIN:
                self.logger.debug("No message available.")
            else:
                self.logger.error(f"ZMQError: {e}")
        except Exception as e:
            self.logger.error(f"Error handling message: {e}")

    def _update_pid_params(self, message: Dict[str, Any]) -> None:
        """Updates PID parameters."""
        pid_name = message.get('pid_name')
        if not pid_name:
            self.logger.error("pid_name not specified in message.")
            return

        pid_instance = self.pid_params.get(pid_name)
        if not pid_instance:
            self.logger.error(f"PID instance {pid_name} not found.")
            return

        pid_instance['kp'] = message.get('kp', pid_instance['kp'])
        pid_instance['ki'] = message.get('ki', pid_instance['ki'])
        pid_instance['kd'] = message.get('kd', pid_instance['kd'])
        pid_instance['control_min'] = message.get('control_min', pid_instance['control_min'])
        pid_instance['control_max'] = message.get('control_max', pid_instance['control_max'])

        self.logger.info(f"Updated PID parameters for {pid_name}: {pid_instance}")

    def _set_control_limits(self, message: Dict[str, Any]) -> None:
        """Sets control limits."""
        control_name = message.get('control_name')
        if not control_name:
            self.logger.error("control_name not specified in message.")
            return

        self.control_limits[control_name] = {
            'limit_min': message.get('limit_min'),
            'limit_max': message.get('limit_max'),
        }
        self.logger.info(f"Set control limits for {control_name}: {self.control_limits[control_name]}")

    def _reset_pid(self, message: Dict[str, Any]) -> None:
        """Resets PID state."""
        pid_name = message.get('pid_name')
        if not pid_name:
            self.logger.error("pid_name not specified in message.")
            return

        pid_instance = self.pid_params.get(pid_name)
        if not pid_instance:
            self.logger.error(f"PID instance {pid_name} not found.")
            return

        # Reset PID state (implementation depends on the PID controller used)
        self.logger.info(f"Reset PID state for {pid_name}")

    def _get_status(self, message: Dict[str, Any]) -> None:
        """Gets PID status."""
        pid_name = message.get('pid_name')
        if not pid_name:
            self.logger.error("pid_name not specified in message.")
            return

        pid_instance = self.pid_params.get(pid_name)
        if not pid_instance:
            self.logger.error(f"PID instance {pid_name} not found.")
            return

        # Retrieve PID status (implementation depends on the PID controller used)
        status = {
            'kp': pid_instance['kp'],
            'ki': pid_instance['ki'],
            'kd': pid_instance['kd'],
            'control_min': pid_instance['control_min'],
            'control_max': pid_instance['control_max'],
            # Add other relevant status information
        }
        self.logger.info(f"Status for {pid_name}: {status}")

    def _set_log_level(self, level_str: str) -> None:
        """Sets the logging level."""
        try:
            level = getattr(logging, level_str.upper(), None)
            if level is None:
                raise ValueError(f"Invalid log level: {level_str}")
            self.logger.setLevel(level)
            self.logger.info(f"Set logging level to {level_str}")
        except ValueError as e:
            self.logger.error(e)

    def _trigger_error(self, message: Dict[str, Any]) -> None:
        """Triggers an error signal."""
        self.set_error_output(True)
        self.logger.error(f"Error triggered: {message}")

    def _clear_error(self, message: Dict[str, Any]) -> None:
        """Clears the error signal."""
        self.set_error_output(False)
        self.logger.info(f"Error cleared: {message}")

    def get_pid_params(self) -> Dict[str, Any]:
        """Returns a copy of the current PID parameters."""
        return self.pid_params.copy()

    def get_control_limits(self) -> Dict[str, Any]:
        """Returns a copy of the current control limits."""
        return self.control_limits.copy()

