#!/usr/bin/env python3
# rgb_led_rainbow_functional.py
# A simple program to control an RGB LED strip using software PWM on a Raspberry Pi.
# This version uses a functional programming style.

import RPi.GPIO as GPIO
import time
from functools import partial

# Define GPIO pins for RGB LED
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

# Define PWM frequency
PWM_FREQUENCY = 200

# Define color list
COLORS = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0), (0, 255, 255)]


def setup_gpio():
    """Sets up the GPIO pins for the RGB LED."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RED_PIN, GPIO.OUT)
        GPIO.setup(GREEN_PIN, GPIO.OUT)
        GPIO.setup(BLUE_PIN, GPIO.OUT)
        return True
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False


def create_pwm_channel(pin, frequency):
    """Creates and starts a PWM channel."""
    try:
        pwm = GPIO.PWM(pin, frequency)
        pwm.start(0)  # Start with 0% duty cycle
        return pwm
    except Exception as e:
        print(f"Error creating PWM channel on pin {pin}: {e}")
        return None


def set_color(pwm_channels, color):
    """Sets the color of the RGB LED using PWM."""
    try:
        red_pwm, green_pwm, blue_pwm = pwm_channels
        red_pwm.ChangeDutyCycle(color[0] / 255 * 100)
        green_pwm.ChangeDutyCycle(color[1] / 255 * 100)
        blue_pwm.ChangeDutyCycle(color[2] / 255 * 100)
    except Exception as e:
        print(f"Error setting color: {e}")


def cleanup_gpio(pwm_channels):
    """Stops PWM and cleans up GPIO pins."""
    try:
        if pwm_channels:
            for pwm in pwm_channels:
                pwm.stop()
        GPIO.cleanup()
        print("GPIO cleanup complete.")
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")


def main():
    """Main function to control the RGB LED."""

    if not setup_gpio():
        return

    red_pwm = create_pwm_channel(RED_PIN, PWM_FREQUENCY)
    green_pwm = create_pwm_channel(GREEN_PIN, PWM_FREQUENCY)
    blue_pwm = create_pwm_channel(BLUE_PIN, PWM_FREQUENCY)

    if not all([red_pwm, green_pwm, blue_pwm]):
        cleanup_gpio([red_pwm, green_pwm, blue_pwm])
        return

    pwm_channels = (red_pwm, green_pwm, blue_pwm)

    try:
        while True:
            for color in COLORS:
                set_color(pwm_channels, color)
                time.sleep(1)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        cleanup_gpio(pwm_channels)


if __name__ == "__main__":
    main()

