#!/usr/bin/env python3

"""
Module: BTS7960BHBridge.py

Description:
This module provides a class for controlling Arduino Motor Shield L293D 
motors with a BCM74HC595 shift register using an Hbridge driver.

Author: Bard
Date: 2023-11-20
Version: 3.0
"""

import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotorShieldError(Exception):
    """Custom exception for MotorShield related errors."""
    pass

class MotorShield:
    """
    A class to control Arduino Motor Shield L293D motors with a BCM74HC595 shift register.
    """

    MOTOR_1 = 1
    MOTOR_2 = 2
    MOTOR_3 = 3
    MOTOR_4 = 4

    DIRECTION_CLOCKWISE = 1
    DIRECTION_COUNTER_CLOCKWISE = 0
    DIRECTION_STOP = 2  # Unique value for stop, simplifies logic

    def __init__(self, use_board=False):
        """
        Initializes the MotorShield.

        Args:
            use_board (bool): True for GPIO.BOARD numbering, False for GPIO.BCM (default).
        """
        try:
            if use_board:
                GPIO.setmode(GPIO.BOARD)
                logging.info("PIN numbering: BOARD")
            else:
                GPIO.setmode(GPIO.BCM)
                logging.info("PIN numbering: BCM")

            self._setup_gpio_pin("latch", 11)
            self._setup_gpio_pin("clock", 9)
            self._setup_gpio_pin("data", 10)
            self._setup_gpio_pin("motor1_pwm", 13)
            self._setup_gpio_pin("motor2_pwm", 12)

            GPIO.setup(self.pins["motor1_pwm"], GPIO.OUT)
            GPIO.setup(self.pins["motor2_pwm"], GPIO.OUT)

            self.pwm_frequency = 100  # Default PWM frequency
            self.motor_pwm = {
                self.MOTOR_1: GPIO.PWM(self.pins["motor1_pwm"], self.pwm_frequency),
                self.MOTOR_2: GPIO.PWM(self.pins["motor2_pwm"], self.pwm_frequency),
            }
            for pwm in self.motor_pwm.values():
                pwm.start(0)

            self.motor_states = {
                self.MOTOR_1: {"direction": self.DIRECTION_STOP, "duty_cycle": 0},
                self.MOTOR_2: {"direction": self.DIRECTION_STOP, "duty_cycle": 0},
            }

            self.directions = {
                self.MOTOR_1: self.DIRECTION_CLOCKWISE,
                self.MOTOR_2: self.DIRECTION_COUNTER_CLOCKWISE,
                self.MOTOR_3: self.DIRECTION_CLOCKWISE,
                self.MOTOR_4: self.DIRECTION_COUNTER_CLOCKWISE
            }

            self._write_to_shift_register(0) # Initialize shift register to 0

        except Exception as e:
            raise MotorShieldError(f"Initialization failed: {e}") from e


    def _setup_gpio_pin(self, pin_name, pin_number):
        """Sets up a GPIO pin as an output."""
        try:
            GPIO.setup(pin_number, GPIO.OUT)
            logging.info(f"{pin_name} pin (GPIO {pin_number}) set up as output.")
            return pin_number
        except Exception as e:
            raise MotorShieldError(f"Failed to set up {pin_name} pin: {e}") from e

    @property
    def pins(self):
        """Returns a dictionary of pin assignments."""
        return self._pins

    @pins.setter
    def pins(self, value):
        """Sets the pin assignments."""
        self._pins = value

    @pins.deleter
    def pins(self):
        del self._pins

    def _write_to_shift_register(self, value):
        """
        Writes a byte to the 74HC595 shift register.

        Args:
            value (int): The byte to write.
        """
        try:
            GPIO.output(self.pins["latch"], GPIO.LOW)

            for _ in range(8):
                GPIO.output(self.pins["clock"], GPIO.LOW)
                GPIO.output(self.pins["data"], value & 0x80)  # Write high bit first
                GPIO.output(self.pins["clock"], GPIO.HIGH)
                value <<= 1  # Shift to next bit

            GPIO.output(self.pins["latch"], GPIO.HIGH)
        except Exception as e:
            raise MotorShieldError(f"Error writing to shift register: {e}") from e

    def _set_motor_direction(self, motor, direction):
        """
        Sets the direction of a motor by writing to the shift register.

        Args:
            motor (int): The motor number.
            direction (int): The direction (0 or 1).
        """
        try:
            current_state = self._read_shift_register()

            if motor == self.MOTOR_1:
                if direction == self.DIRECTION_CLOCKWISE:
                    self._write_to_shift_register(current_state | 0b00000010)
                elif direction == self.DIRECTION_COUNTER_CLOCKWISE:
                    self._write_to_shift_register(current_state & 0b11111101)
                else: # Stop
                    self._write_to_shift_register(current_state & 0b11111101) # Set to CCW to ensure proper stop

            elif motor == self.MOTOR_2:
                if direction == self.DIRECTION_CLOCKWISE:
                    self._write_to_shift_register(current_state | 0b00001000)
                elif direction == self.DIRECTION_COUNTER_CLOCKWISE:
                    self._write_to_shift_register(current_state & 0b11110111)
                else: # Stop
                    self._write_to_shift_register(current_state & 0b11110111) # Set to CCW to ensure proper stop
            else:
                raise ValueError("Invalid motor number.")

            self.motor_states[motor]["direction"] = direction
            logging.debug(f"Motor {motor} direction set to {direction} (0=CCW, 1=CW, 2=Stop)")

        except Exception as e:
            raise MotorShieldError(f"Error setting motor direction: {e}") from e

    def _read_shift_register(self):
        """Reads the current state of the shift register."""
        raise NotImplementedError("_read_shift_register must be implemented by subclass.")

    def set_pwm_frequency(self, frequency):
        """
        Sets the PWM frequency for both motors.

        Args:
            frequency (int): The PWM frequency in Hz.
        """
        try:
            if not isinstance(frequency, int) or frequency <= 0:
                raise ValueError("Frequency must be a positive integer.")

            for motor, pwm in self.motor_pwm.items():
                pwm.ChangeFrequency(frequency)
            self.pwm_frequency = frequency
            logging.info(f"PWM frequency set to {frequency} Hz.")
        except ValueError as ve:
            logging.error(f"Invalid frequency provided: {ve}")
        except Exception as e:
            logging.error(f"Error setting PWM frequency: {e}")

    def set_motor_pwm(self, motor, duty_cycle):
        """
        Sets the PWM duty cycle for a motor.

        Args:
            motor (int): The motor number.
            duty_cycle (float): The duty cycle (0.0 to 100.0).
        """
        try:
            if not self.MOTOR_1 <= motor <= self.MOTOR_2:
                raise ValueError(f"Invalid motor number: {motor}")
            if not 0.0 <= duty_cycle <= 100.0:
                raise ValueError(f"Invalid duty cycle: {duty_cycle}. Must be between 0.0 and 100.0")

            self.motor_pwm[motor].ChangeDutyCycle(duty_cycle)
            self.motor_states[motor]["duty_cycle"] = duty_cycle
            logging.debug(f"Motor {motor} duty cycle set to {duty_cycle}%.")

        except ValueError as ve:
            logging.error(f"Invalid input: {ve}")
        except Exception as e:
            logging.error(f"Error setting motor PWM: {e}")

    def start_motor(self, motor, direction, duty_cycle=100):
        """
        Starts a motor in a specified direction at a given duty cycle.

        Args:
            motor (int): The motor number.
            direction (int): The direction (0 or 1).
            duty_cycle (float): The duty cycle (0.0 to 100.0). Defaults to 100.0.
        """
        try:
            if not self.MOTOR_1 <= motor <= self.MOTOR_2:
                raise ValueError(f"Invalid motor number: {motor}")
            if not 0.0 <= duty_cycle <= 100.0:
                raise ValueError(f"Invalid duty cycle: {duty_cycle}. Must be between 0.0 and 100.0")

            self._set_motor_direction(motor, direction)
            self.set_motor_pwm(motor, duty_cycle)
            logging.info(f"Motor {motor} started. Direction: {direction}, Duty cycle: {duty_cycle}%")

        except ValueError as ve:
            logging.error(f"Invalid input: {ve}")
        except Exception as e:
            logging.error(f"Error starting motor: {e}")

    def stop_motor(self, motor):
        """
        Stops a motor by setting the PWM duty cycle to 0 and setting the direction bits
        in the shift register to stop the motor.

        Args:
            motor (int): The motor number.
        """
        try:
            if not self.MOTOR_1 <= motor <= self.MOTOR_2:
                raise ValueError(f"Invalid motor number: {motor}")

            self.set_motor_pwm(motor, 0)
            # Ensure motor is stopped by setting direction bits appropriately
            self._set_motor_direction(motor, self.DIRECTION_STOP)
            logging.info(f"Motor {motor} stopped.")

        except ValueError as ve:
            logging.error(f"Invalid input: {ve}")
        except Exception as e:
            logging.error(f"Error stopping motor: {e}")

    def stop_all_motors(self):
        """Stops all motors."""
        try:
            for motor in range(self.MOTOR_1, self.MOTOR_2 + 1):
                self.stop_motor(motor)
            logging.info("All motors stopped.")
        except Exception as e:
            logging.error(f"Error stopping all motors: {e}")

    def change_duty_cycle(self, motor, duty_cycle):
        """
        Changes the duty cycle of a running motor.

        Args:
            motor (int): The motor number.
            duty_cycle (float): The new duty cycle (0.0 to 100.0).
        """
        try:
            if not self.MOTOR_1 <= motor <= self.MOTOR_2:
                raise ValueError(f"Invalid motor number: {motor}")
            if not 0.0 <= duty_cycle <= 100.0:
                raise ValueError(f"Invalid duty cycle: {duty_cycle}. Must be between 0.0 and 100.0")

            self.set_motor_pwm(motor, duty_cycle)
            logging.info(f"Motor {motor} duty cycle changed to {duty_cycle}%.")

        except ValueError as ve:
            logging.error(f"Invalid input: {ve}")
        except Exception as e:
            logging.error(f"Error changing duty cycle: {e}")

    def __enter__(self):
        """Context manager entry point."""
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Context manager exit point.  Stops motors and cleans up GPIO."""
        try:
            self.stop_all_motors()
            logging.info("All motors stopped in context manager exit.")
        except Exception as e:
            logging.error(f"Error stopping motors in context manager: {e}")
        finally:
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    try:
        with MotorShield(use_board=False) as shield:
            # Example usage:
            shield.start_motor(MotorShield.MOTOR_1, MotorShield.DIRECTION_CLOCKWISE, 75)
            shield.start_motor(MotorShield.MOTOR_2, MotorShield.DIRECTION_COUNTER_CLOCKWISE, 50)
            time.sleep(5)
            shield.change_duty_cycle(MotorShield.MOTOR_1, 25)
            time.sleep(5)
            shield.stop_all_motors()

    except MotorShieldError as e:
        logging.error(f"MotorShield error: {e}")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")

