#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus2
import time
import datetime
import signal
import sys
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DS1338Error(Exception):
    """Base class for DS1338-specific exceptions."""
    pass

class DS1338CommunicationError(DS1338Error):
    """Raised when I2C communication fails."""
    pass

class DS1338InvalidDataError(DS1338Error):
    """Raised when RTC data is invalid."""
    pass

class DS1338:
    """DS1338 Real-Time Clock Driver."""

    _REG_SECONDS = 0x00
    _REG_MINUTES = 0x01
    _REG_HOURS = 0x02
    _REG_DAY = 0x03
    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06
    _REG_CONTROL = 0x07
    _REG_STATUS = 0x0F  # Added Status Register address

    def __init__(self, twi=1, addr=0x68, retry_attempts=3):
        """Initialize the DS1338 driver."""
        self._bus = None
        self._twi = twi
        self._addr = addr
        self._retry_attempts = retry_attempts
        self._initialize_bus()
        self._validate_rtc_data()  # Initial validation

    def _initialize_bus(self):
        """Initialize the I2C bus with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                self._bus = smbus2.SMBus(self._twi)
                logging.info("I2C bus initialized successfully.")
                return  # Exit if successful
            except Exception as e:
                logging.error(f"Failed to initialize I2C bus (attempt {attempt + 1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to initialize I2C bus after multiple retries.") from e
                time.sleep(1)  # Wait before retrying

    def _check_rtc_presence(self):
        """Check if the RTC is present by reading the status register."""
        try:
            self._read_register(self._REG_STATUS)
            logging.info("DS1338 RTC found.")
            return True
        except DS1338CommunicationError as e:
            logging.error(f"DS1338 RTC not found: {e}")
            return False

    def _write_register(self, register, data):
        """Write data to a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                self._bus.write_byte_data(self._addr, register, data)
                return
            except OSError as e:
                logging.error(f"I2C write error (attempt {attempt + 1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to write to RTC after multiple retries.") from e
                time.sleep(0.1)  # Wait before retrying

    def _read_register(self, register):
        """Read data from a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                data = self._bus.read_byte_data(self._addr, register)
                return data
            except OSError as e:
                logging.error(f"I2C read error (attempt {attempt + 1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to read from RTC after multiple retries.") from e
                time.sleep(0.1)  # Wait before retrying


    def _bcd_to_int(self, bcd):
        """Decode a 2x4bit BCD to an integer."""
        return int(str(bcd // 16) + str(bcd % 16))


    def _int_to_bcd(self, n):
        """Encode a one or two digits number to the BCD."""

        tens = n // 10
        units = n % 10
        return (tens * 16) + units

    def _read_time_register(self, register):
        """Read and decode a time register (seconds, minutes, etc.)."""
        try:
            return self._bcd_to_int(self._read_register(register))
        except DS1338CommunicationError as e:
            raise DS1338CommunicationError(f"Failed to read time register {register}: {e}") from e

    def _write_time_register(self, register, value):
        """Write and encode a time register (seconds, minutes, etc.)."""
        if not 0 <= value <= 59:
            raise ValueError("Invalid time value (0-59 expected)")
        try:
            self._write_register(register, self._int_to_bcd(value))
        except DS1338CommunicationError as e:
            raise DS1338CommunicationError(f"Failed to write time register {register}: {e}") from e

    def _read_rtc_data(self):
        """Read the whole time from the RTC."""
        try:
            seconds = self._read_time_register(self._REG_SECONDS)
            minutes = self._read_time_register(self._REG_MINUTES)
            hours = (self._read_register(self._REG_HOURS) & 0x3F)
            day = self._read_time_register(self._REG_DAY)
            date = self._read_time_register(self._REG_DATE)
            month = self._read_time_register(self._REG_MONTH)
            year = self._read_time_register(self._REG_YEAR)
            return year, month, date, day, hours, minutes, seconds
        except DS1338CommunicationError as e:
            raise DS1338CommunicationError(f"Failed to read RTC data: {e}") from e


    def _validate_rtc_data(self):
        """Validate the RTC data read from the RTC."""
        try:
            year, month, date, day, hours, minutes, seconds = self._read_rtc_data()

            if not 0 <= seconds <= 59:
                raise DS1338InvalidDataError("Invalid seconds value")
            if not 0 <= minutes <= 59:
                raise DS1338InvalidDataError("Invalid minutes value")
            if not 0 <= hours <= 23:
                raise DS1338InvalidDataError("Invalid hours value")
            if not 1 <= day <= 7:
                raise DS1338InvalidDataError("Invalid day value")
            if not 1 <= date <= 31:
                raise DS1338InvalidDataError("Invalid date value")
            if not 1 <= month <= 12:
                raise DS1338InvalidDataError("Invalid month value")

            logging.debug(f"RTC data validated: Year={year}, Month={month}, Date={date}, Day={day}, Hours={hours}, Minutes={minutes}, Seconds={seconds}")

        except DS1338CommunicationError as e:
            raise DS1338CommunicationError(f"Failed to validate RTC data (communication error): {e}") from e
        except DS1338InvalidDataError as e:
            raise DS1338InvalidDataError(f"Failed to validate RTC data: {e}") from e


    def read_datetime(self, century=21):
        """Read the current time from the RTC and return a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self._read_rtc_data()
            year = (century - 1) * 100 + year # Add century
            return datetime.datetime(year, month, date, hours, minutes, seconds)
        except DS1338CommunicationError as e:
            raise DS1338CommunicationError(f"Failed to read datetime: {e}") from e
        except ValueError as e:  # Catch invalid date/time values
            raise DS1338InvalidDataError(f"Invalid RTC data: {e}") from e


    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """Write all time parameters to the RTC."""

        if seconds is not None:
            self._write_time_register(self._REG_SECONDS, seconds)
        if minutes is not None:
            self._write_time_register(self._REG_MINUTES, minutes)
        if hours is not None:
            if not 0 <= hours <= 23:
                raise ValueError("Invalid hours value (0-23 expected)")

            # Preserve the 12/24 hour mode flag.  The top bit of the hours
