            hours = (hours & 0x3F) | top_bit

            self._write_register(self._REG_HOURS, hours)

        if day is not None:
            if not 1 <= day <= 7:
                raise ValueError("Invalid day value (1-7 expected)")
            self._write_time_register(self._REG_DAY, day)
        if date is not None:
            if not 1 <= date <= 31:
                raise ValueError("Invalid date value (1-31 expected)")
            self._write_time_register(self._REG_DATE, date)
        if month is not None:
            if not 1 <= month <= 12:
                raise ValueError("Invalid month value (1-12 expected)")
            self._write_time_register(self._REG_MONTH, month)
        if year is not None:
            if not 0 <= year <= 99:
                raise ValueError("Invalid year value (0-99 expected)")
            self._write_time_register(self._REG_YEAR, year)

        # After writing all the fields validate the entire time again.
        self._validate_rtc_data()


def main():
    """Main entry point for the time setting script."""

    # Check if the script is run with root privileges.  The RTC driver
    # often needs these to be able to access the I2C bus.
    if process_is_running_with_effective_privileges():
