    # Set the RTC to the current time.
    rtc.write_all(year=now.year % 100, month=now.month, date=now.day, day=now.isoweekday(), hours=now.hour, minutes=now.minute, seconds=now.second)

    # Read back the time and verify it was set correctly.
    rtc_datetime = rtc.read_datetime()
    logging.info(f"RTC time: {rtc_datetime}")


def process_is_running_with_effective_privileges():
    """Return True if the process is running with effective root privileges."""
    return sys.platform == "linux" and os.geteuid() == 0


