import serial
import time

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
LOG_FILE = 'access_log.txt'
READ_TIMEOUT = 1  # seconds

def read_rfid_tag(serial_connection):
    """Reads an RFID tag ID from the serial port."""
    try:
        tag_data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return tag_data
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None
    except UnicodeDecodeError as e:
        print(f"Decoding error: {e}")
        return None

def log_access(tag_id, log_filepath):
    """Logs the access event to a file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(log_filepath, 'a') as log_file:
            log_file.write(log_entry)
        print(f'Access granted for RFID Tag: {tag_id}')
    except IOError as e:
        print(f"File I/O error: {e}")

def main():
    """Main function to continuously monitor RFID reader."""
    serial_connection = None
    try:
        # Initialize serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Connected to RFID reader on {SERIAL_PORT}")

        while True:
            tag_id = read_rfid_tag(serial_connection)
            if tag_id:
                log_access(tag_id, LOG_FILE)
            time.sleep(0.1)  # Reduced sleep to avoid excessive CPU usage

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial port is closed on exit
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

