LOG_FILE = 'power_consumption.log'

def read_power_data(serial_connection):
    """Reads a line of data from the serial port, parses it as a power value, and returns the value."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print(f"{datetime.datetime.now()} - Warning: Invalid data received from meter.", file=sys.stderr)
        return None
    except Exception as e:
        print(f"{datetime.datetime.now()} - Error reading data: {e}", file=sys.stderr)
        return None

def log_power_usage(power_value, log_filepath):
    """Logs the power usage to a file with a timestamp."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(log_filepath, 'a') as log_file:
            log_file.write(log_entry)
    except IOError as e:
        print(f"{datetime.datetime.now()} - Error writing to log file: {e}", file=sys.stderr)

def main():
    """Main function to read power data from the meter and log it."""
    try:
        # Initialize serial connection
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1) as ser:
            print(f"Connected to serial port {SERIAL_PORT}")
            while True:
                power_value = read_power_data(ser)
                if power_value is not None:
                    log_power_usage(power_value, LOG_FILE)
                    print(f"Power: {power_value} W")
                time.sleep(1)  # Reduced sleep time for responsiveness
    except serial.SerialException as e:
        print(f"{datetime.datetime.now()} - Error opening serial port: {e}", file=sys.stderr)
