        print(f"{datetime.datetime.now()} - OS Error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"{datetime.datetime.now()} - An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

