        return Response(response.replace('\n', '<br>'), mimetype='text/html')
    except serial.SerialException as e:
        return Response(f"Error communicating with instrument: {e}", mimetype='text/plain', status=503)

@app.route('/getdata')
def get_all_items():
    """Returns the entire list of items as JSON."""
    return jsonify(store)

@app.route('/getset/<int:item_id>')
def get_item_by_id(item_id):
    """Returns a specific item by its ID as JSON."""
    item = next((item for item in store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)

@app.route('/getpost/<int:item_id>/<name>')
def create_item(item_id, name):
    """Creates a new item with the given ID and name (GET method)."""
    new_id = item_id
    new_item = {
        "id": new_id,
        "name": name,
        "done": False
    }
    store.append(new_item)
    return jsonify(store)

@app.route('/postjson', methods=['POST', 'GET'])
def create_item_json():
    """Creates a new item with JSON payload or returns the current list (POST/GET)."""
    if request.method == 'POST':
        try:
            if request.is_json:
                data = request.get_json()
            else:
                data = request.form  # Handle form data if not JSON

            new_id = (store[-1]['id'] + 1) if store else 1 # Auto-increment ID
            new_name = data.get('name', '') # Default to empty if not provided
            new_done = data.get('done', False) == 'True' # Treat "True" and "true" as boolean

            new_item = {
                "id": new_id,
                "name": new_name,
                "done": new_done
            }
            store.append(new_item)
            return jsonify(store)
        except (KeyError, TypeError) as e:
            abort(400, f"Invalid input format: {e}")
    else:
        return jsonify(store)


if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

