import serial
import time

# Define the Bluetooth device address and baud rate
BLUETOOTH_DEVICE = '/dev/rfcomm4'
BLUETOOTH_BAUD_RATE = 38400

def connect_bluetooth(device, baud):
    """Establishes a serial connection to the Bluetooth device."""
    try:
        bluetooth = serial.Serial(device, baud)
        return bluetooth
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

def send_command(bluetooth, command):
    """Sends a command to the Bluetooth device."""
    try:
        message = f'X{command}\n'
        bluetooth.write(message.encode())
        print(f"Sent: {message.strip()}")
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    """Main function to handle user input and send commands."""
    bluetooth = None
    try:
        # Establish Bluetooth connection
        bluetooth = connect_bluetooth(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)
        print("Bluetooth connection established.")

        # Continuously prompt for commands
        while True:
            try:
                user_input = input("Enter command (or 'exit' to quit): ")
                if user_input.lower() == "exit":
                    break
                send_command(bluetooth, user_input)
                time.sleep(0.1)  # Add a small delay
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except KeyboardInterrupt:
        print("\nExiting program.")
    except RuntimeError as e:
        print(f"Fatal Error: {e}")
    finally:
        # Ensure serial connection is closed
        if bluetooth and bluetooth.is_open:
            bluetooth.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

